import { Component, computed, input, output } from '@angular/core';
import { TablerIconComponent, IconDots } from '@tabler/icons-angular';

/** 1 hành động: key (id phát ra), icon Tabler, label (aria/tooltip — bên gọi cấp, i18n), danger, disabled. */
export interface HrmActionItem {
  key: string;
  icon: unknown;
  label?: string;
  danger?: boolean;
  disabled?: boolean;
}

/** hrm-action-cell — cụm nút icon cuối dòng bảng. Hiện tối đa `max` nút; dư → nút "…" phát key '__more__'.
 *  Nhấn nút phát (action)=key; tự chặn nổi bọt để không kích hoạt click cả dòng. */
@Component({
  selector: 'hrm-action-cell',
  imports: [TablerIconComponent],
  template: `
    @for (a of visible(); track a.key) {
      <button type="button" class="ac-btn" [class.ac-danger]="a.danger" [disabled]="a.disabled"
        [attr.aria-label]="a.label || null" [attr.title]="a.label || null" (click)="fire(a.key, $event)">
        <tabler-icon [icon]="$any(a.icon)" [size]="18" />
      </button>
    }
    @if (hasOverflow()) {
      <button type="button" class="ac-btn" [attr.aria-label]="moreLabel() || null" [attr.title]="moreLabel() || null"
        (click)="fire('__more__', $event)">
        <tabler-icon [icon]="dots" [size]="18" />
      </button>
    }
  `,
  host: { class: 'hrm-action-cell', '[class.hrm-action-cell--bordered]': 'bordered()' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 2px; }
.ac-btn { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px;
  padding: 0; border: none; background: transparent; color: var(--icon-secondary);
  border-radius: var(--radius-md); cursor: pointer; transition: background var(--duration-fast) var(--ease-out),
  color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out); }
.ac-btn:hover { background: var(--overlay-hover); color: var(--icon-primary); }
.ac-btn:disabled { color: var(--icon-disabled); cursor: not-allowed; background: transparent; }
.ac-btn.ac-danger:hover { background: var(--error-bg); color: var(--error-base); }

/* bordered: mỗi nút là ô viền bo góc riêng (kiểu icon-button có khung) — khoảng cách control
   ↔ control = --space-2. Dùng cho thẻ/toolbar cần nút nổi khối, không phải hàng bảng. */
:host(.hrm-action-cell--bordered) { gap: var(--space-2); }
:host(.hrm-action-cell--bordered) .ac-btn { width: 34px; height: 34px; border: 1px solid var(--border-sub); background: var(--bg-surface); }
:host(.hrm-action-cell--bordered) .ac-btn:hover { border-color: var(--primary-base); background: var(--bg-surface); color: var(--primary-base); }
:host(.hrm-action-cell--bordered) .ac-btn.ac-danger:hover { border-color: var(--error-base); background: var(--error-bg); color: var(--error-base); }
  `],
})
export class HrmActionCell {
  readonly actions = input<HrmActionItem[]>([]);
  readonly max = input(3);
  /** Nút dạng ô viền bo góc riêng (icon-button có khung) — cho thẻ/toolbar. Mặc định phẳng (hàng bảng). */
  readonly bordered = input(false);
  /** Nhãn nút "…" (aria/tooltip) — bên gọi cấp để i18n. */
  readonly moreLabel = input('');
  readonly action = output<string>();

  protected readonly dots = IconDots;
  protected readonly visible = computed(() => this.actions().slice(0, this.max()));
  protected readonly hasOverflow = computed(() => this.actions().length > this.max());

  protected fire(key: string, e: Event): void {
    e.stopPropagation();
    this.action.emit(key);
  }
}
